                        if difference is not None:
                            return
                elif kind is str:
                    if len(left) != len(right):
                        record(where, left, right, 'length')
                    elif len(left) > string_limit:
                        limited = True
                    elif left != right:
                        record(where, left, right)
                elif kind in (int, bool) or left is None:
